//! Ported from src/log.c (CodeCoreMorph, D-68): options, messages and the log.

use std::fmt;
use std::io::Write;

/// Log levels, most severe first: a message less severe than the options' level is dropped.
pub const ERROR: i32 = 0;
pub const WARN: i32 = 1;
pub const INFO: i32 = 2;
pub const DEBUG: i32 = 3;

/// The longest message, with C's NUL: a longer formatted message is cut short.
pub const MESSAGE_MAX: usize = 160;

/// Section and key names are lowercased.
pub const CASE_FOLD: u32 = 0x01;
/// A key set again replaces its value without a warning.
pub const ALLOW_DUP: u32 = 0x02;
/// Every value is a string.
pub const NO_TYPES: u32 = 0x04;

const LEVEL_NAMES: [&str; 4] = ["error", "warning", "info", "debug"];

/// A level's name in messages: `error`, `warning`, `info`, `debug`, or `unknown`.
pub fn level_name(level: i32) -> &'static str {
    usize::try_from(level)
        .ok()
        .and_then(|i| LEVEL_NAMES.get(i))
        .copied()
        .unwrap_or("unknown")
}

/// Why an operation failed: the C library's status codes, which are negative.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    NoMemory,
    Syntax,
    Range,
    NotFound,
    Type,
    Io,
}

impl Error {
    /// The C status code.
    pub fn code(self) -> i32 {
        match self {
            Error::NoMemory => -1,
            Error::Syntax => -2,
            Error::Range => -3,
            Error::NotFound => -4,
            Error::Type => -5,
            Error::Io => -6,
        }
    }

    pub fn from_code(code: i32) -> Option<Error> {
        [Error::NoMemory, Error::Syntax, Error::Range, Error::NotFound, Error::Type, Error::Io]
            .into_iter()
            .find(|e| e.code() == code)
    }

    pub fn message(self) -> &'static str {
        match self {
            Error::NoMemory => "out of memory",
            Error::Syntax => "syntax error",
            Error::Range => "value out of range",
            Error::NotFound => "no such key",
            Error::Type => "wrong type",
            Error::Io => "read error",
        }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.message())
    }
}

impl std::error::Error for Error {}

/// A status code's message: `no error` for 0, `unknown error` for a code the library doesn't
/// have.
pub fn strerror(code: i32) -> &'static str {
    if code == 0 {
        return "no error";
    }
    Error::from_code(code).map_or("unknown error", Error::message)
}

/// Where messages go: each formatted message, with its level.
pub type Sink<'a> = &'a dyn Fn(i32, &[u8]);

/// Parser options.
#[derive(Clone, Copy)]
pub struct Options<'a> {
    /// `CASE_FOLD`, `ALLOW_DUP`, `NO_TYPES`.
    pub flags: u32,
    /// Starts a comment, besides `;`.
    pub comment: u8,
    /// Messages less severe than this are dropped.
    pub log_level: i32,
    /// None: messages go to stderr.
    pub log: Option<Sink<'a>>,
}

impl Default for Options<'_> {
    fn default() -> Self {
        Options { flags: 0, comment: b'#', log_level: WARN, log: None }
    }
}

impl fmt::Debug for Options<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Options")
            .field("flags", &self.flags)
            .field("comment", &(self.comment as char))
            .field("log_level", &self.log_level)
            .field("log", &self.log.is_some())
            .finish()
    }
}

impl Options<'_> {
    /// Whether a message of `level` gets through.
    pub fn enabled(&self, level: i32) -> bool {
        level <= self.log_level
    }

    /// A message that is already formatted: to the sink, or to stderr as
    /// `kvconf: <level>: <message>`.
    pub fn write(&self, level: i32, message: &[u8]) {
        if !self.enabled(level) {
            return;
        }
        match self.log {
            Some(sink) => sink(level, message),
            None => {
                let mut line = format!("kvconf: {}: ", level_name(level)).into_bytes();
                line.extend_from_slice(message);
                line.push(b'\n');
                let _ = std::io::stderr().write_all(&line);
            }
        }
    }

    /// A message to format, cut short at `MESSAGE_MAX - 1` bytes as C's buffer did.
    pub fn log(&self, level: i32, args: fmt::Arguments<'_>) {
        if !self.enabled(level) {
            return;
        }
        let text = args.to_string();
        let bytes = text.as_bytes();
        self.write(level, &bytes[..bytes.len().min(MESSAGE_MAX - 1)]);
    }
}

//! The C functions of src/log.c, exported under their names over `crate::log`. The
//! printf-style `kv_log` and `kv_vlog` stay C (Rust can't define them): they format the message
//! and call `kv_log_write`.

use std::ffi::{c_char, c_int, CStr};

use super::sys;
use crate::log::{level_name, strerror, Options};

/// The C strings of the module's names and messages, which C callers keep.
const TEXTS: [&CStr; 13] = [
    c"error",
    c"warning",
    c"info",
    c"debug",
    c"unknown",
    c"no error",
    c"out of memory",
    c"syntax error",
    c"value out of range",
    c"no such key",
    c"wrong type",
    c"read error",
    c"unknown error",
];

/// `text` as a static C string; every text the module gives is in `TEXTS`.
pub(super) fn c_text(text: &str) -> *const c_char {
    TEXTS.iter().find(|t| t.to_bytes() == text.as_bytes()).map_or(c"?".as_ptr(), |t| t.as_ptr())
}

/// Calls `f` with C's options as Rust's: their sink calls C's with its context. NULL options
/// are the defaults.
pub(super) unsafe fn with_options<R>(opt: *const sys::kv_options, f: impl FnOnce(&Options) -> R) -> R {
    if opt.is_null() {
        return f(&Options::default());
    }
    let c = &*opt;
    let ctx = c.log_ctx;
    let sink = c.log.map(|log| {
        move |level: i32, message: &[u8]| {
            let mut text = message.to_vec();
            text.push(0);
            // SAFETY: C's sink takes its own context and a NUL-terminated message.
            unsafe { log(ctx, level, text.as_ptr().cast()) }
        }
    });
    let options = Options {
        flags: c.flags,
        comment: c.comment as u8,
        log_level: c.log_level,
        log: sink.as_ref().map(|s| s as &dyn Fn(i32, &[u8])),
    };
    f(&options)
}

#[no_mangle]
pub unsafe extern "C" fn kv_options_init(opt: *mut sys::kv_options) {
    let defaults = Options::default();
    (*opt).flags = defaults.flags;
    (*opt).comment = defaults.comment as c_char;
    (*opt).log_level = defaults.log_level;
    (*opt).log = None;
    (*opt).log_ctx = std::ptr::null_mut();
}

#[no_mangle]
pub extern "C" fn kv_level_name(level: c_int) -> *const c_char {
    c_text(level_name(level))
}

#[no_mangle]
pub extern "C" fn kv_strerror(code: c_int) -> *const c_char {
    c_text(strerror(code))
}

#[no_mangle]
pub unsafe extern "C" fn kv_log_write(
    opt: *const sys::kv_options,
    level: c_int,
    message: *const c_char,
) {
    let message = CStr::from_ptr(message).to_bytes();
    with_options(opt, |o| o.write(level, message));
}

