/*
 * log.c - what stays C of the log (CodeCoreMorph, D-70): the printf-style entry
 * points, which stable Rust can't define. They format the message and hand it to
 * kv_log_write; the retirement deletes them with the rest of the C.
 */
#include "kvint.h"

void kv_vlog(const kv_options *opt, int level, const char *fmt, va_list ap)
{
    char buf[KV_MESSAGE_MAX];
    vsnprintf(buf, sizeof buf, fmt, ap); /* a longer message is cut short */
    kv_log_write(opt, level, buf);
}

void kv_log(const kv_options *opt, int level, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    kv_vlog(opt, level, fmt, ap);
    va_end(ap);
}

//! Ported from src/strutil.c (CodeCoreMorph, D-68): string helpers. ASCII only, as the C was:
//! names are ASCII, and C's ctype functions depended on the locale.

use crate::log::{Error, CASE_FOLD};

/// The longest section or key name, with C's NUL.
pub const NAME_MAX: usize = 64;

/// A space or a tab.
pub fn is_space(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

/// Where `s` is once spaces and tabs are trimmed off both ends: `(start, len)`.
pub fn trim_range(s: &[u8]) -> (usize, usize) {
    let start = s.iter().position(|&c| !is_space(c)).unwrap_or(s.len());
    let end = s.iter().rposition(|&c| !is_space(c)).map_or(start, |e| e + 1);
    (start, end - start)
}

/// `s` without spaces and tabs at either end.
pub fn trim(s: &[u8]) -> &[u8] {
    let (start, len) = trim_range(s);
    &s[start..start + len]
}

/// Compares `a` and `b` without ASCII case, as C's did: the difference of the first lowercased
/// bytes that differ (the end counting as 0).
pub fn casecmp(a: &[u8], b: &[u8]) -> i32 {
    let mut i = 0;
    loop {
        let ca = a.get(i).map_or(0, u8::to_ascii_lowercase);
        let cb = b.get(i).map_or(0, u8::to_ascii_lowercase);
        if ca != cb || ca == 0 {
            return i32::from(ca) - i32::from(cb);
        }
        i += 1;
    }
}

/// Compares the bytes of `prefix` with the whole of `word` without ASCII case: 0 when they
/// are the same word, as C's `kvi_casencmp` did for its first `len` bytes.
pub fn prefix_casecmp(prefix: &[u8], word: &[u8]) -> i32 {
    for (i, &c) in prefix.iter().enumerate() {
        let ca = c.to_ascii_lowercase();
        let cb = word.get(i).map_or(0, u8::to_ascii_lowercase);
        if ca != cb {
            return i32::from(ca) - i32::from(cb);
        }
        if cb == 0 {
            return 0;
        }
    }
    if prefix.len() >= word.len() {
        0
    } else {
        -1
    }
}

/// Names are letters, digits, `_`, `-` and `.`, and not empty.
pub fn valid_name(s: &[u8]) -> bool {
    !s.is_empty()
        && s.iter().all(|&c| c.is_ascii_alphanumeric() || c == b'_' || c == b'-' || c == b'.')
}

/// A name as a document keeps it: lowercased with `CASE_FOLD`; `Error::Range` when it is too
/// long for C's `NAME_MAX` buffer.
pub fn name(s: &[u8], flags: u32) -> Result<Vec<u8>, Error> {
    if s.len() >= NAME_MAX {
        return Err(Error::Range);
    }
    let mut out = s.to_vec();
    if flags & CASE_FOLD != 0 {
        out.make_ascii_lowercase();
    }
    Ok(out)
}

//! The C functions of src/strutil.c, exported under their names over `crate::strutil`.

use std::ffi::{c_char, c_int, c_uint, c_void, CStr};

use crate::strutil;

extern "C" {
    fn malloc(size: usize) -> *mut c_void;
}

/// The `len` bytes at `s`.
pub(super) unsafe fn bytes<'a>(s: *const c_char, len: usize) -> &'a [u8] {
    if len == 0 {
        return &[];
    }
    std::slice::from_raw_parts(s.cast::<u8>(), len)
}

/// A copy of `s` from C's allocator, NUL-terminated: what C code may `free`.
pub(super) unsafe fn c_copy(s: &[u8]) -> *mut c_char {
    let copy = malloc(s.len() + 1).cast::<u8>();
    if !copy.is_null() {
        std::ptr::copy_nonoverlapping(s.as_ptr(), copy, s.len());
        *copy.add(s.len()) = 0;
    }
    copy.cast::<c_char>()
}

/// Writes `name` and a NUL into a C name buffer, which holds `strutil::NAME_MAX` bytes.
pub(super) unsafe fn put_name(dst: *mut c_char, name: &[u8]) {
    std::ptr::copy_nonoverlapping(name.as_ptr(), dst.cast::<u8>(), name.len());
    *dst.add(name.len()) = 0;
}

#[no_mangle]
pub unsafe extern "C" fn kvi_strndup(s: *const c_char, len: usize) -> *mut c_char {
    c_copy(bytes(s, len))
}

#[no_mangle]
pub unsafe extern "C" fn kvi_casecmp(a: *const c_char, b: *const c_char) -> c_int {
    strutil::casecmp(CStr::from_ptr(a).to_bytes(), CStr::from_ptr(b).to_bytes())
}

#[no_mangle]
pub unsafe extern "C" fn kvi_casencmp(a: *const c_char, b: *const c_char, len: usize) -> c_int {
    strutil::prefix_casecmp(bytes(a, len), CStr::from_ptr(b).to_bytes())
}

#[no_mangle]
pub unsafe extern "C" fn kvi_trim(s: *mut *const c_char, len: usize) -> usize {
    let (start, n) = strutil::trim_range(bytes(*s, len));
    *s = (*s).add(start);
    n
}

#[no_mangle]
pub unsafe extern "C" fn kvi_lower(s: *mut c_char) {
    let len = CStr::from_ptr(s).to_bytes().len();
    std::slice::from_raw_parts_mut(s.cast::<u8>(), len).make_ascii_lowercase();
}

#[no_mangle]
pub unsafe extern "C" fn kvi_valid_name(s: *const c_char, len: usize) -> c_int {
    c_int::from(strutil::valid_name(bytes(s, len)))
}

#[no_mangle]
pub unsafe extern "C" fn kvi_copy_name(
    dst: *mut c_char,
    src: *const c_char,
    len: usize,
    flags: c_uint,
) -> c_int {
    match strutil::name(bytes(src, len), flags) {
        Ok(name) => {
            put_name(dst, &name);
            0
        }
        Err(e) => e.code(),
    }
}

//! Ported from src/value.c (CodeCoreMorph, D-68): typed values, what a value's text means, and
//! back. C's `kv_value` is a tagged union; here it is an enum.

use crate::log::{Error, NO_TYPES};
use crate::strutil;

/// The type numbers of C's `kv_type`, which `type_name` takes.
pub const NONE: i32 = 0;
pub const INT: i32 = 1;
pub const REAL: i32 = 2;
pub const BOOL: i32 = 3;
pub const STR: i32 = 4;

const TYPE_NAMES: [&str; 5] = ["none", "int", "real", "bool", "string"];

/// A type's name, by its number: `?` for one C doesn't have.
pub fn type_name(number: i32) -> &'static str {
    usize::try_from(number).ok().and_then(|i| TYPE_NAMES.get(i)).copied().unwrap_or("?")
}

/// A typed value. Strings are bytes: a file need not be UTF-8.
#[derive(Debug, Clone, PartialEq, Default)]
pub enum Value {
    #[default]
    None,
    Int(i64),
    Real(f64),
    Bool(bool),
    Str(Vec<u8>),
}

impl Value {
    /// C's type number.
    pub fn type_number(&self) -> i32 {
        match self {
            Value::None => NONE,
            Value::Int(_) => INT,
            Value::Real(_) => REAL,
            Value::Bool(_) => BOOL,
            Value::Str(_) => STR,
        }
    }

    pub fn type_name(&self) -> &'static str {
        type_name(self.type_number())
    }

    /// What `text` means, trimmed: a quoted string, else (unless `NO_TYPES`) a boolean, an
    /// integer or a real, else the text itself. A number that doesn't fit is `Error::Range`;
    /// a bad quoted string, `Error::Syntax`.
    pub fn parse(text: &[u8], flags: u32) -> Result<Value, Error> {
        let text = strutil::trim(text);
        if text.first() == Some(&b'"') {
            return unquote(text).map(Value::Str);
        }
        if flags & NO_TYPES == 0 {
            if let Some(b) = parse_bool(text) {
                return Ok(Value::Bool(b));
            }
            if let Some(n) = parse_int(text) {
                return n.map(Value::Int);
            }
            if let Some(r) = parse_real(text) {
                return r.map(Value::Real);
            }
        }
        Ok(Value::Str(text.to_vec()))
    }

    /// The value as kvdump prints it: an integer as `%ld`, a real as `%g`, `true` or `false`,
    /// a string quoted, with its escapes; nothing for none.
    pub fn format(&self) -> Vec<u8> {
        match self {
            Value::None => Vec::new(),
            Value::Int(n) => n.to_string().into_bytes(),
            Value::Real(r) => format_g(*r).into_bytes(),
            Value::Bool(b) => (if *b { "true" } else { "false" }).as_bytes().to_vec(),
            Value::Str(s) => {
                let mut out = Vec::with_capacity(s.len() + 2);
                out.push(b'"');
                for &c in s {
                    match c {
                        b'"' => out.extend_from_slice(b"\\\""),
                        b'\\' => out.extend_from_slice(b"\\\\"),
                        b'\n' => out.extend_from_slice(b"\\n"),
                        b'\t' => out.extend_from_slice(b"\\t"),
                        _ => out.push(c),
                    }
                }
                out.push(b'"');
                out
            }
        }
    }

    pub fn as_int(&self) -> Result<i64, Error> {
        match self {
            Value::Int(n) => Ok(*n),
            _ => Err(Error::Type),
        }
    }

    /// An integer is a real too.
    pub fn as_real(&self) -> Result<f64, Error> {
        match self {
            Value::Real(r) => Ok(*r),
            Value::Int(n) => Ok(*n as f64),
            _ => Err(Error::Type),
        }
    }

    pub fn as_bool(&self) -> Result<bool, Error> {
        match self {
            Value::Bool(b) => Ok(*b),
            _ => Err(Error::Type),
        }
    }

    pub fn as_str(&self) -> Option<&[u8]> {
        match self {
            Value::Str(s) => Some(s),
            _ => None,
        }
    }
}

fn parse_bool(s: &[u8]) -> Option<bool> {
    const WORDS: [(&[u8], bool); 6] = [
        (b"yes", true), (b"true", true), (b"on", true),
        (b"no", false), (b"false", false), (b"off", false),
    ]; // fmt: skip
    WORDS.iter().find(|(word, _)| s.eq_ignore_ascii_case(word)).map(|&(_, b)| b)
}

/// `Some(Ok)` for an integer, `Some(Err(Range))` for one too big for C's `long`, `None` for
/// text that isn't one. As C's `strtol` with base 0: `0x1f` is hex and `010` octal, so `08`
/// is no number at all.
fn parse_int(s: &[u8]) -> Option<Result<i64, Error>> {
    if s.is_empty() || s.len() >= 32 {
        return None;
    }
    let (negative, digits) = match s[0] {
        b'+' => (false, &s[1..]),
        b'-' => (true, &s[1..]),
        _ => (false, s),
    };
    if digits.is_empty() || !digits.iter().all(|c| c.is_ascii_hexdigit() || c | 0x20 == b'x') {
        return None;
    }
    let hex = digits.len() > 2 && digits[0] == b'0' && digits[1] | 0x20 == b'x';
    let (radix, body) = if hex {
        (16, &digits[2..])
    } else if digits[0] == b'0' {
        (8, digits)
    } else {
        (10, digits)
    };
    let mut magnitude: u64 = 0;
    let mut overflow = false;
    for &c in body {
        let d = u64::from(char::from(c).to_digit(radix)?);
        match magnitude.checked_mul(u64::from(radix)).and_then(|m| m.checked_add(d)) {
            Some(m) => magnitude = m,
            None => overflow = true,
        }
    }
    let limit = if negative { 1u64 << 63 } else { i64::MAX as u64 };
    if overflow || magnitude > limit {
        return Some(Err(Error::Range));
    }
    Some(Ok(if negative { (magnitude as i64).wrapping_neg() } else { magnitude as i64 }))
}

/// Like `parse_int`, for numbers with a `.` or an exponent: `inf` and `nan` are text, and a
/// number too big for a double is `Error::Range`.
fn parse_real(s: &[u8]) -> Option<Result<f64, Error>> {
    if s.is_empty() || s.len() >= 64 {
        return None;
    }
    if !s.iter().all(|&c| c.is_ascii_digit() || matches!(c, b'+' | b'-' | b'.' | b'e' | b'E')) {
        return None;
    }
    if !s.iter().any(|&c| matches!(c, b'.' | b'e' | b'E')) {
        return None;
    }
    let r: f64 = std::str::from_utf8(s).ok()?.parse().ok()?;
    Some(if r.is_infinite() { Err(Error::Range) } else { Ok(r) })
}

/// A quoted string's bytes: `\"`, `\\`, `\n` and `\t` are the escapes.
fn unquote(s: &[u8]) -> Result<Vec<u8>, Error> {
    if s.len() < 2 || s[s.len() - 1] != b'"' {
        return Err(Error::Syntax);
    }
    let inner = &s[1..s.len() - 1];
    let mut out = Vec::with_capacity(inner.len());
    let mut i = 0;
    while i < inner.len() {
        let c = match inner[i] {
            b'"' => return Err(Error::Syntax),
            b'\\' => {
                i += 1;
                match inner.get(i) {
                    Some(b'"') => b'"',
                    Some(b'\\') => b'\\',
                    Some(b'n') => b'\n',
                    Some(b't') => b'\t',
                    _ => return Err(Error::Syntax),
                }
            }
            c => c,
        };
        out.push(c);
        i += 1;
    }
    Ok(out)
}

/// `printf("%g", r)`: six significant digits, without trailing zeros; an exponent of at least
/// two digits when it is below -4 or from 6 on.
pub fn format_g(r: f64) -> String {
    if r.is_nan() {
        return if r.is_sign_negative() { "-nan" } else { "nan" }.to_string();
    }
    if r.is_infinite() {
        return if r < 0.0 { "-inf" } else { "inf" }.to_string();
    }
    if r == 0.0 {
        return if r.is_sign_negative() { "-0" } else { "0" }.to_string();
    }
    let scientific = format!("{r:.5e}");
    let (mantissa, exponent) = scientific.split_once('e').unwrap_or((&scientific, "0"));
    let exponent: i32 = exponent.parse().unwrap_or(0);
    if (-4..6).contains(&exponent) {
        let decimals = usize::try_from(5 - exponent).unwrap_or(0);
        strip_zeros(&format!("{r:.decimals$}")).to_string()
    } else {
        let sign = if exponent < 0 { '-' } else { '+' };
        format!("{}e{sign}{:02}", strip_zeros(mantissa), exponent.abs())
    }
}

fn strip_zeros(digits: &str) -> &str {
    if digits.contains('.') {
        digits.trim_end_matches('0').trim_end_matches('.')
    } else {
        digits
    }
}

//! The C functions of src/value.c, exported under their names over `crate::value`. A C
//! `kv_value` keeps its union as C's; its string comes from C's allocator, NUL-terminated,
//! since C code frees it.

use std::ffi::{c_char, c_int, c_uint, c_void, CStr};

use super::strutil::{bytes, c_copy};
use super::sys;
use crate::log::Error;
use crate::value::{type_name, Value};

extern "C" {
    fn free(ptr: *mut c_void);
}

/// The Rust value of a C one.
pub(super) unsafe fn to_rust(v: &sys::kv_value) -> Value {
    match v.type_ {
        sys::kv_type_KV_INT => Value::Int(v.u.i),
        sys::kv_type_KV_REAL => Value::Real(v.u.r),
        sys::kv_type_KV_BOOL => Value::Bool(v.u.b != 0),
        sys::kv_type_KV_STR => Value::Str(bytes(v.u.s.ptr, v.u.s.len).to_vec()),
        _ => Value::None,
    }
}

/// Empties a C value: its string goes back to C's allocator.
pub(super) unsafe fn clear(v: &mut sys::kv_value) {
    if v.type_ == sys::kv_type_KV_STR {
        free(v.u.s.ptr.cast::<c_void>());
    }
    *v = std::mem::zeroed();
    v.type_ = sys::kv_type_KV_NONE;
}

/// Puts `value` in a C value, emptied first; `Error::NoMemory` leaves it as it was.
pub(super) unsafe fn store(v: &mut sys::kv_value, value: &Value) -> Result<(), Error> {
    let string = match value {
        Value::Str(s) => {
            let copy = c_copy(s);
            if copy.is_null() {
                return Err(Error::NoMemory);
            }
            Some((copy, s.len()))
        }
        _ => None,
    };
    clear(v);
    match value {
        Value::None => {}
        Value::Int(n) => {
            v.type_ = sys::kv_type_KV_INT;
            v.u.i = *n;
        }
        Value::Real(r) => {
            v.type_ = sys::kv_type_KV_REAL;
            v.u.r = *r;
        }
        Value::Bool(b) => {
            v.type_ = sys::kv_type_KV_BOOL;
            v.u.b = c_int::from(*b);
        }
        Value::Str(_) => {
            if let Some((ptr, len)) = string {
                v.type_ = sys::kv_type_KV_STR;
                v.u.s.ptr = ptr;
                v.u.s.len = len;
            }
        }
    }
    Ok(())
}

fn status(result: Result<(), Error>) -> c_int {
    result.map_or_else(Error::code, |()| 0)
}

#[no_mangle]
pub unsafe extern "C" fn kv_value_parse(
    v: *mut sys::kv_value,
    text: *const c_char,
    len: usize,
    flags: c_uint,
) -> c_int {
    status(Value::parse(bytes(text, len), flags).and_then(|value| store(&mut *v, &value)))
}

#[no_mangle]
pub unsafe extern "C" fn kv_value_set_str(
    v: *mut sys::kv_value,
    s: *const c_char,
    len: usize,
) -> c_int {
    status(store(&mut *v, &Value::Str(bytes(s, len).to_vec())))
}

#[no_mangle]
pub unsafe extern "C" fn kv_value_copy(
    dst: *mut sys::kv_value,
    src: *const sys::kv_value,
) -> c_int {
    if std::ptr::eq(dst, src) {
        return 0;
    }
    let value = to_rust(&*src);
    status(store(&mut *dst, &value))
}

/// Like `snprintf`: the length the whole text needs, as much of it as fits in `buf` with a
/// NUL.
#[no_mangle]
pub unsafe extern "C" fn kv_value_format(
    v: *const sys::kv_value,
    buf: *mut c_char,
    size: usize,
) -> c_int {
    let text = to_rust(&*v).format();
    if size > 0 {
        let n = text.len().min(size - 1);
        std::ptr::copy_nonoverlapping(text.as_ptr(), buf.cast::<u8>(), n);
        *buf.add(n) = 0;
    }
    c_int::try_from(text.len()).unwrap_or(c_int::MAX)
}

#[no_mangle]
pub unsafe extern "C" fn kv_value_clear(v: *mut sys::kv_value) {
    clear(&mut *v);
}

/// The type names as the static C strings C callers keep.
const NAMES: [&CStr; 6] = [c"none", c"int", c"real", c"bool", c"string", c"?"];

#[no_mangle]
pub extern "C" fn kv_type_name(number: sys::kv_type) -> *const c_char {
    let name = type_name(i32::try_from(number).unwrap_or(-1));
    NAMES.iter().find(|n| n.to_bytes() == name.as_bytes()).map_or(c"?".as_ptr(), |n| n.as_ptr())
}

//! Ported from src/doc.c (CodeCoreMorph, D-68): documents, their entries by section and key in
//! the order they were first set.

use crate::log::{Error, CASE_FOLD};
use crate::strutil;
use crate::value::Value;

/// The entries a document first makes room for.
pub const MIN_ENTRIES: usize = 8;

/// The room a document with `capacity` entries grows to: doubling from `MIN_ENTRIES`.
pub fn grown(capacity: usize) -> usize {
    if capacity == 0 {
        MIN_ENTRIES
    } else {
        capacity.saturating_mul(2)
    }
}

/// Whether two section or key names are the same under a document's flags.
pub fn same_name(flags: u32, a: &[u8], b: &[u8]) -> bool {
    if flags & CASE_FOLD != 0 {
        a.eq_ignore_ascii_case(b)
    } else {
        a == b
    }
}

/// What setting a key did.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Set {
    /// A new entry, last.
    Added,
    /// An earlier entry's value, which keeps its place.
    Replaced,
}

impl Set {
    /// C's return value: 0 or 1.
    pub fn code(self) -> i32 {
        match self {
            Set::Added => 0,
            Set::Replaced => 1,
        }
    }
}

/// One entry of a document.
#[derive(Debug, Clone, PartialEq)]
pub struct Entry {
    /// Empty before the first section.
    pub section: Vec<u8>,
    pub key: Vec<u8>,
    pub value: Value,
    /// Where it was last set.
    pub line: i32,
}

/// What a document holds.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Stats {
    /// Distinct section names, the empty one included.
    pub sections: usize,
    pub entries: usize,
    /// By C's type number (`value::NONE` ... `value::STR`).
    pub by_type: [usize; 5],
    pub longest_string: usize,
}

impl Stats {
    /// The stats of entries, as `(section, value)` in the document's order.
    pub fn of<'a>(flags: u32, entries: impl IntoIterator<Item = (&'a [u8], &'a Value)>) -> Stats {
        let mut stats = Stats::default();
        let mut sections: Vec<&[u8]> = Vec::new();
        for (section, value) in entries {
            stats.entries += 1;
            if !sections.iter().any(|s| same_name(flags, s, section)) {
                sections.push(section);
                stats.sections += 1;
            }
            if let Some(n) = usize::try_from(value.type_number()).ok().and_then(|i| stats.by_type.get_mut(i)) {
                *n += 1;
            }
            if let Value::Str(s) = value {
                stats.longest_string = stats.longest_string.max(s.len());
            }
        }
        stats
    }
}

/// A document: entries in the order they were first set, found by section and key.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Doc {
    entries: Vec<Entry>,
    /// The options' flags it was parsed with: `CASE_FOLD` makes names compare without case.
    pub flags: u32,
}

impl Doc {
    pub fn new(flags: u32) -> Doc {
        Doc { entries: Vec::new(), flags }
    }

    pub fn entries(&self) -> &[Entry] {
        &self.entries
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// The entry of `key` in `section` (None: before the first section).
    pub fn find(&self, section: Option<&[u8]>, key: &[u8]) -> Option<&Entry> {
        let section = section.unwrap_or_default();
        self.entries.iter().find(|e| {
            same_name(self.flags, &e.key, key) && same_name(self.flags, &e.section, section)
        })
    }

    /// Sets a key: a new entry goes last, with its names lowercased under `CASE_FOLD`; a name
    /// too long for C's buffer is `Error::Range`.
    pub fn set(
        &mut self,
        section: Option<&[u8]>,
        key: &[u8],
        value: &Value,
        line: i32,
    ) -> Result<Set, Error> {
        let section = section.unwrap_or_default();
        let flags = self.flags;
        if let Some(e) = self.entries.iter_mut().find(|e| {
            same_name(flags, &e.key, key) && same_name(flags, &e.section, section)
        }) {
            e.value = value.clone();
            e.line = line;
            return Ok(Set::Replaced);
        }
        let section = strutil::name(section, flags)?;
        let key = strutil::name(key, flags)?;
        self.entries.push(Entry { section, key, value: value.clone(), line });
        Ok(Set::Added)
    }

    fn value(&self, section: Option<&[u8]>, key: &[u8]) -> Result<&Value, Error> {
        self.find(section, key).map(|e| &e.value).ok_or(Error::NotFound)
    }

    pub fn get_int(&self, section: Option<&[u8]>, key: &[u8]) -> Result<i64, Error> {
        self.value(section, key)?.as_int()
    }

    /// An integer is a real too.
    pub fn get_real(&self, section: Option<&[u8]>, key: &[u8]) -> Result<f64, Error> {
        self.value(section, key)?.as_real()
    }

    pub fn get_bool(&self, section: Option<&[u8]>, key: &[u8]) -> Result<bool, Error> {
        self.value(section, key)?.as_bool()
    }

    /// A string's bytes; None when the key is missing or isn't a string.
    pub fn get_str(&self, section: Option<&[u8]>, key: &[u8]) -> Option<&[u8]> {
        self.find(section, key)?.value.as_str()
    }

    /// The entries of one section, or every entry when `section` is None, in order.
    pub fn each<'a>(&'a self, section: Option<&'a [u8]>) -> impl Iterator<Item = &'a Entry> + 'a {
        self.entries
            .iter()
            .filter(move |e| section.is_none_or(|s| same_name(self.flags, &e.section, s)))
    }

    pub fn stats(&self) -> Stats {
        Stats::of(self.flags, self.entries.iter().map(|e| (e.section.as_slice(), &e.value)))
    }
}

//! The C functions of src/doc.c, exported under their names over `crate::doc`. A C `kv_doc` stays
//! C's: C code reads its `entries` (from C's allocator), `count` and `error`, so the bridge keeps
//! them as the C did, with the module's rules for names, growth and stats.

use std::ffi::{c_char, c_int, c_void, CStr};

use super::strutil::put_name;
use super::sys;
use super::value::{clear, store, to_rust};
use crate::doc::{grown, same_name, Set, Stats};
use crate::log::Error;
use crate::strutil;
use crate::value::Value;

extern "C" {
    fn realloc(ptr: *mut c_void, size: usize) -> *mut c_void;
    fn free(ptr: *mut c_void);
}

/// A C name buffer's bytes, up to its NUL.
fn name(buffer: &[c_char]) -> &[u8] {
    let len = buffer.iter().position(|&c| c == 0).unwrap_or(buffer.len());
    // SAFETY: c_char and u8 have the same size and alignment.
    unsafe { std::slice::from_raw_parts(buffer.as_ptr().cast::<u8>(), len) }
}

unsafe fn text<'a>(s: *const c_char) -> &'a [u8] {
    if s.is_null() {
        b""
    } else {
        CStr::from_ptr(s).to_bytes()
    }
}

/// The entry `i` of a C document.
unsafe fn entry<'a>(doc: *const sys::kv_doc, i: usize) -> &'a mut sys::kv_entry {
    &mut *(*doc).entries.add(i)
}

unsafe fn lookup(
    doc: *const sys::kv_doc,
    section: *const c_char,
    key: *const c_char,
) -> *mut sys::kv_entry {
    let (section, key) = (text(section), text(key));
    let flags = (*doc).flags;
    for i in 0..(*doc).count {
        let e = entry(doc, i);
        if same_name(flags, name(&e.key), key) && same_name(flags, name(&e.section), section) {
            return e;
        }
    }
    std::ptr::null_mut()
}

#[no_mangle]
pub unsafe extern "C" fn kv_doc_init(doc: *mut sys::kv_doc) {
    *doc = std::mem::zeroed();
}

#[no_mangle]
pub unsafe extern "C" fn kv_doc_free(doc: *mut sys::kv_doc) {
    for i in 0..(*doc).count {
        clear(&mut entry(doc, i).value);
    }
    free((*doc).entries.cast::<c_void>());
    kv_doc_init(doc);
}

#[no_mangle]
pub unsafe extern "C" fn kv_doc_set(
    doc: *mut sys::kv_doc,
    section: *const c_char,
    key: *const c_char,
    v: *const sys::kv_value,
    line: c_int,
) -> c_int {
    let value = to_rust(&*v);
    let found = lookup(doc, section, key);
    if !found.is_null() {
        if let Err(e) = store(&mut (*found).value, &value) {
            return e.code();
        }
        (*found).line = line;
        return Set::Replaced.code();
    }
    let d = &mut *doc;
    if d.count == d.capacity {
        let capacity = grown(d.capacity);
        let entries = realloc(d.entries.cast::<c_void>(), capacity * size_of::<sys::kv_entry>());
        if entries.is_null() {
            return Error::NoMemory.code();
        }
        d.entries = entries.cast::<sys::kv_entry>();
        d.capacity = capacity;
    }
    let (Ok(section), Ok(key)) =
        (strutil::name(text(section), d.flags), strutil::name(text(key), d.flags))
    else {
        return Error::Range.code();
    };
    let e = &mut *d.entries.add(d.count);
    *e = std::mem::zeroed();
    put_name(e.section.as_mut_ptr(), &section);
    put_name(e.key.as_mut_ptr(), &key);
    if let Err(err) = store(&mut e.value, &value) {
        return err.code();
    }
    e.line = line;
    d.count += 1;
    Set::Added.code()
}

#[no_mangle]
pub unsafe extern "C" fn kv_find(
    doc: *const sys::kv_doc,
    section: *const c_char,
    key: *const c_char,
) -> *const sys::kv_entry {
    lookup(doc, section, key)
}

/// The value of a key, or why there is none.
unsafe fn value(
    doc: *const sys::kv_doc,
    section: *const c_char,
    key: *const c_char,
) -> Result<Value, Error> {
    let e = lookup(doc, section, key);
    if e.is_null() {
        return Err(Error::NotFound);
    }
    Ok(to_rust(&(*e).value))
}

#[no_mangle]
pub unsafe extern "C" fn kv_get_int(
    doc: *const sys::kv_doc,
    section: *const c_char,
    key: *const c_char,
    out: *mut std::ffi::c_long,
) -> c_int {
    match value(doc, section, key).and_then(|v| v.as_int()) {
        Ok(n) => {
            *out = n;
            0
        }
        Err(e) => e.code(),
    }
}

#[no_mangle]
pub unsafe extern "C" fn kv_get_real(
    doc: *const sys::kv_doc,
    section: *const c_char,
    key: *const c_char,
    out: *mut f64,
) -> c_int {
    match value(doc, section, key).and_then(|v| v.as_real()) {
        Ok(r) => {
            *out = r;
            0
        }
        Err(e) => e.code(),
    }
}

#[no_mangle]
pub unsafe extern "C" fn kv_get_bool(
    doc: *const sys::kv_doc,
    section: *const c_char,
    key: *const c_char,
    out: *mut c_int,
) -> c_int {
    match value(doc, section, key).and_then(|v| v.as_bool()) {
        Ok(b) => {
            *out = c_int::from(b);
            0
        }
        Err(e) => e.code(),
    }
}

/// The C document's own string, which stays valid while the entry does.
#[no_mangle]
pub unsafe extern "C" fn kv_get_str(
    doc: *const sys::kv_doc,
    section: *const c_char,
    key: *const c_char,
    fallback: *const c_char,
) -> *const c_char {
    let e = lookup(doc, section, key);
    if e.is_null() || (*e).value.type_ != sys::kv_type_KV_STR {
        return fallback;
    }
    (*e).value.u.s.ptr
}

#[no_mangle]
pub unsafe extern "C" fn kv_each(
    doc: *const sys::kv_doc,
    section: *const c_char,
    visit: sys::kv_visit_fn,
    ctx: *mut c_void,
) -> c_int {
    let Some(visit) = visit else {
        return 0;
    };
    let wanted = (!section.is_null()).then(|| text(section));
    let mut i = 0;
    while i < (*doc).count {
        let e = entry(doc, i);
        if wanted.is_none_or(|s| same_name((*doc).flags, name(&e.section), s)) {
            let rc = visit(ctx, e);
            if rc != 0 {
                return rc;
            }
        }
        i += 1;
    }
    0
}

#[no_mangle]
pub unsafe extern "C" fn kv_doc_stats(doc: *const sys::kv_doc, stats: *mut sys::kv_stats) {
    let entries: Vec<(Vec<u8>, Value)> = (0..(*doc).count)
        .map(|i| {
            let e = entry(doc, i);
            (name(&e.section).to_vec(), to_rust(&e.value))
        })
        .collect();
    let found = Stats::of((*doc).flags, entries.iter().map(|(s, v)| (s.as_slice(), v)));
    let out = &mut *stats;
    out.sections = found.sections;
    out.entries = found.entries;
    out.by_type = found.by_type;
    out.longest_string = found.longest_string;
}

//! Ported from src/parse.c (CodeCoreMorph, D-68): reading files. `scan` finds the entries;
//! `parse_into` keeps them in a document.
//!
//! A line is blank, a comment (`;`, or the options' comment character), a section (`[name]`)
//! or an entry (`key = value`). An unquoted value ends at a comment character that follows a
//! space; a quoted one at its closing quote.

use std::fmt;
use std::io::Read;

use crate::doc::{Doc, Set};
use crate::log::{Error, Options, ALLOW_DUP, DEBUG, ERROR, WARN};
use crate::strutil;
use crate::value::Value;

/// Where and why parsing stopped: `column` is 1-based, 0 when it is about the whole line.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParseError {
    pub code: Error,
    pub line: i32,
    pub column: i32,
    pub message: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}

impl std::error::Error for ParseError {}

/// Why a scan stopped early: the text, or the visitor's non-zero code.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Stop {
    Error(ParseError),
    Visitor(i32),
}

fn lossy(s: &[u8]) -> std::borrow::Cow<'_, str> {
    String::from_utf8_lossy(s)
}

fn is_comment(opt: &Options, c: u8) -> bool {
    c == b';' || c == opt.comment
}

/// Only a comment, or nothing, may follow a section's `]` or a closing quote.
fn blank_rest(opt: &Options, s: &[u8]) -> bool {
    strutil::trim(s).first().is_none_or(|&c| is_comment(opt, c))
}

/// One line, and the column numbers of its bytes.
struct Line<'o, 'a> {
    opt: &'o Options<'a>,
    number: i32,
}

impl Line<'_, '_> {
    /// Logs why the scan stops; column 0 is the whole line.
    fn fail(&self, column: usize, code: Error, what: &str) -> Stop {
        let column = i32::try_from(column).unwrap_or(i32::MAX);
        if column > 0 {
            self.opt.log(ERROR, format_args!("line {}, column {column}: {what}", self.number));
        } else {
            self.opt.log(ERROR, format_args!("line {}: {what}", self.number));
        }
        Stop::Error(ParseError { code, line: self.number, column, message: what.to_string() })
    }
}

/// `(offset, len)` of `s[from..to]` trimmed, as offsets into `s`.
fn trimmed(s: &[u8], from: usize, to: usize) -> (usize, usize) {
    let (start, len) = strutil::trim_range(&s[from..to]);
    (from + start, len)
}

/// Finds the entries of `text` (C's `kv_scan`): `visit(section, key, raw, line)` gets each,
/// its value as written (quotes included), and a non-zero return stops the scan. Errors are
/// logged through the options.
pub fn scan<F>(text: &[u8], opt: &Options, mut visit: F) -> Result<(), Stop>
where
    F: FnMut(&[u8], &[u8], &[u8], i32) -> i32,
{
    let mut section: Vec<u8> = Vec::new();
    let mut number = 0;
    let mut rest = text;
    while !rest.is_empty() {
        let (raw_line, next) = match rest.iter().position(|&c| c == b'\n') {
            Some(i) => (&rest[..i], &rest[i + 1..]),
            None => (rest, &rest[rest.len()..]),
        };
        rest = next;
        number += 1;
        let line = Line { opt, number };
        let l = raw_line.strip_suffix(b"\r").unwrap_or(raw_line);
        let (start, n) = trimmed(l, 0, l.len());
        let end = start + n;
        if n == 0 || is_comment(opt, l[start]) {
            continue;
        }
        if l[start] == b'[' {
            let Some(close) = l[start..end].iter().position(|&c| c == b']').map(|i| start + i)
            else {
                return Err(line.fail(start + 1, Error::Syntax, "missing ']'"));
            };
            if !blank_rest(opt, &l[close + 1..end]) {
                return Err(line.fail(close + 2, Error::Syntax, "text after ']'"));
            }
            let (name_at, name_len) = trimmed(l, start + 1, close);
            let name = &l[name_at..name_at + name_len];
            if !strutil::valid_name(name) {
                return Err(line.fail(name_at + 1, Error::Syntax, "bad section name"));
            }
            section = strutil::name(name, opt.flags)
                .map_err(|e| line.fail(name_at + 1, e, "section name too long"))?;
            opt.log(DEBUG, format_args!("line {number}: section {}", lossy(&section)));
            continue;
        }
        let Some(eq) = l[start..end].iter().position(|&c| c == b'=').map(|i| start + i) else {
            return Err(line.fail(0, Error::Syntax, "expected '='"));
        };
        let (key_at, key_len) = trimmed(l, start, eq);
        let key = &l[key_at..key_at + key_len];
        if !strutil::valid_name(key) {
            return Err(line.fail(key_at + 1, Error::Syntax, "bad key name"));
        }
        let key = strutil::name(key, opt.flags)
            .map_err(|e| line.fail(key_at + 1, e, "key name too long"))?;
        let (v_at, v_len) = trimmed(l, eq + 1, end);
        let v = &l[v_at..v_at + v_len];
        let value = if v.first() == Some(&b'"') {
            let mut i = 1;
            while i < v.len() && v[i] != b'"' {
                if v[i] == b'\\' && i + 1 < v.len() {
                    i += 1;
                }
                i += 1;
            }
            if i >= v.len() {
                return Err(line.fail(v_at + 1, Error::Syntax, "missing '\"'"));
            }
            if !blank_rest(opt, &v[i + 1..]) {
                return Err(line.fail(v_at + i + 2, Error::Syntax, "text after the closing quote"));
            }
            &v[..=i]
        } else {
            let cut = (1..v.len())
                .find(|&i| is_comment(opt, v[i]) && strutil::is_space(v[i - 1]))
                .unwrap_or(v.len());
            strutil::trim(&v[..cut])
        };
        let rc = visit(&section, &key, value, number);
        if rc != 0 {
            return Err(Stop::Visitor(rc));
        }
    }
    Ok(())
}

/// Where `parse_into` keeps entries: Rust's `Doc`, or a C document through the bridge.
pub trait Store {
    /// The document is parsed with these flags (`CASE_FOLD` compares names without case).
    fn set_flags(&mut self, flags: u32);
    fn set(&mut self, section: &[u8], key: &[u8], value: &Value, line: i32) -> Result<Set, Error>;
}

impl Store for Doc {
    fn set_flags(&mut self, flags: u32) {
        self.flags = flags;
    }

    fn set(&mut self, section: &[u8], key: &[u8], value: &Value, line: i32) -> Result<Set, Error> {
        Doc::set(self, Some(section), key, value, line)
    }
}

/// Parses `text` into `store` (C's `kv_parse_string`): each entry's value is typed and set, and
/// a key set again is warned about unless `ALLOW_DUP`. The entries before an error stay.
pub fn parse_into<S: Store>(store: &mut S, text: &[u8], opt: &Options) -> Result<(), ParseError> {
    store.set_flags(opt.flags);
    let mut failure: Option<ParseError> = None;
    let scanned = scan(text, opt, |section, key, raw, line| {
        match Value::parse(raw, opt.flags).and_then(|v| store.set(section, key, &v, line)) {
            Ok(Set::Replaced) if opt.flags & ALLOW_DUP == 0 => {
                let dot = if section.is_empty() { "" } else { "." };
                opt.log(
                    WARN,
                    format_args!("line {line}: {}{dot}{} is set again", lossy(section), lossy(key)),
                );
                0
            }
            Ok(_) => 0,
            Err(e) => {
                let mut message = format!("{}: {}", lossy(key), e.message());
                message.truncate(crate::log::MESSAGE_MAX - 1);
                opt.log(ERROR, format_args!("line {line}: {message}"));
                let code = e.code();
                failure = Some(ParseError { code: e, line, column: 0, message });
                code
            }
        }
    });
    match scanned {
        Ok(()) => Ok(()),
        Err(Stop::Error(e)) => Err(e),
        Err(Stop::Visitor(code)) => Err(failure.unwrap_or_else(|| ParseError {
            code: Error::from_code(code).unwrap_or(Error::Syntax),
            line: 0,
            column: 0,
            message: crate::log::strerror(code).to_string(),
        })),
    }
}

/// Reads a whole file into `store`, as C's `kv_parse_file` did: text after a NUL byte is
/// ignored, and a read error is `Error::Io`.
pub fn read_into<S: Store, R: Read>(
    store: &mut S,
    mut reader: R,
    opt: &Options,
) -> Result<(), ParseError> {
    let mut text = Vec::new();
    if reader.read_to_end(&mut text).is_err() {
        return Err(read_error());
    }
    parse_into(store, until_nul(&text), opt)
}

/// The text a C string of `bytes` holds: up to its first NUL.
pub fn until_nul(bytes: &[u8]) -> &[u8] {
    bytes.iter().position(|&c| c == 0).map_or(bytes, |i| &bytes[..i])
}

/// A file that couldn't be read.
pub fn read_error() -> ParseError {
    ParseError { code: Error::Io, line: 0, column: 0, message: Error::Io.message().to_string() }
}

impl Doc {
    /// A document of `text`.
    pub fn parse(text: &[u8], opt: &Options) -> Result<Doc, ParseError> {
        let mut doc = Doc::default();
        parse_into(&mut doc, text, opt)?;
        Ok(doc)
    }
}

//! The C functions of src/parse.c, exported under their names over `crate::parse`. A C
//! document takes the entries through `kv_doc_set`, as C's parser did, and keeps why parsing
//! stopped in its `error`.

use std::ffi::{c_char, c_int, c_void, CStr};

use super::log::with_options;
use super::strutil::bytes;
use super::sys;
use super::value::{clear, store};
use crate::doc::Set;
use crate::log::{Error, MESSAGE_MAX};
use crate::parse::{parse_into, read_error, scan, until_nul, ParseError, Stop, Store};
use crate::value::Value;

extern "C" {
    fn fread(ptr: *mut c_void, size: usize, n: usize, fp: *mut sys::FILE) -> usize;
    fn ferror(fp: *mut sys::FILE) -> c_int;
}

/// `s` with a NUL, for C.
fn c_string(s: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len() + 1);
    out.extend_from_slice(s);
    out.push(0);
    out
}

/// A C error record of `e`, its message cut to fit.
unsafe fn record(err: *mut sys::kv_error, e: &ParseError) {
    if err.is_null() {
        return;
    }
    let out = &mut *err;
    *out = std::mem::zeroed();
    out.code = e.code.code();
    out.line = e.line;
    out.column = e.column;
    let n = e.message.len().min(MESSAGE_MAX - 1);
    std::ptr::copy_nonoverlapping(e.message.as_ptr(), out.message.as_mut_ptr().cast::<u8>(), n);
}

/// A C document, which takes entries through `kv_doc_set`.
struct CDoc(*mut sys::kv_doc);

impl Store for CDoc {
    fn set_flags(&mut self, flags: u32) {
        // SAFETY: the C caller's document, alive for the call.
        unsafe { (*self.0).flags = flags }
    }

    fn set(&mut self, section: &[u8], key: &[u8], value: &Value, line: i32) -> Result<Set, Error> {
        let (section, key) = (c_string(section), c_string(key));
        // SAFETY: a value of our own, emptied before it goes; the document is the caller's.
        unsafe {
            let mut v: sys::kv_value = std::mem::zeroed();
            store(&mut v, value)?;
            let rc = super::doc::kv_doc_set(self.0, section.as_ptr().cast(), key.as_ptr().cast(), &v, line);
            clear(&mut v);
            match rc {
                0 => Ok(Set::Added),
                1 => Ok(Set::Replaced),
                code => Err(Error::from_code(code).unwrap_or(Error::NoMemory)),
            }
        }
    }
}

#[no_mangle]
pub unsafe extern "C" fn kv_scan(
    text: *const c_char,
    len: usize,
    opt: *const sys::kv_options,
    visit: sys::kv_event_fn,
    ctx: *mut c_void,
    err: *mut sys::kv_error,
) -> c_int {
    if !err.is_null() {
        *err = std::mem::zeroed();
    }
    let text = bytes(text, len);
    let scanned = with_options(opt, |o| {
        scan(text, o, |section, key, raw, line| {
            let Some(visit) = visit else {
                return 0;
            };
            let (section, key, raw) = (c_string(section), c_string(key), c_string(raw));
            // SAFETY: C's visitor gets NUL-terminated strings that live through the call.
            unsafe { visit(ctx, section.as_ptr().cast(), key.as_ptr().cast(), raw.as_ptr().cast(), line) }
        })
    });
    match scanned {
        Ok(()) => 0,
        Err(Stop::Visitor(code)) => code,
        Err(Stop::Error(e)) => {
            record(err, &e);
            e.code.code()
        }
    }
}

/// Parses `text` into a C document, whose `error` says why it stopped.
unsafe fn parse_c(doc: *mut sys::kv_doc, text: &[u8], opt: *const sys::kv_options) -> c_int {
    (*doc).error = std::mem::zeroed();
    match with_options(opt, |o| parse_into(&mut CDoc(doc), text, o)) {
        Ok(()) => 0,
        Err(e) => {
            record(&mut (*doc).error, &e);
            e.code.code()
        }
    }
}

#[no_mangle]
pub unsafe extern "C" fn kv_parse_string(
    doc: *mut sys::kv_doc,
    text: *const c_char,
    opt: *const sys::kv_options,
) -> c_int {
    parse_c(doc, CStr::from_ptr(text).to_bytes(), opt)
}

#[no_mangle]
pub unsafe extern "C" fn kv_parse_file(
    doc: *mut sys::kv_doc,
    fp: *mut sys::FILE,
    opt: *const sys::kv_options,
) -> c_int {
    let mut text = Vec::new();
    let mut chunk = [0u8; 4096];
    loop {
        let got = fread(chunk.as_mut_ptr().cast(), 1, chunk.len(), fp);
        text.extend_from_slice(&chunk[..got]);
        if got == 0 {
            break;
        }
    }
    if ferror(fp) != 0 {
        (*doc).error = std::mem::zeroed();
        record(&mut (*doc).error, &read_error());
        return Error::Io.code();
    }
    parse_c(doc, until_nul(&text), opt)
}

