//! Ported from tools/kvdump.c (CodeCoreMorph, D-68): print a configuration file's entries with
//! their types.
//!
//! usage: kvdump [-f] [-t] [-q | -v] [-s section] file
//!
//!   -f          fold section and key names to lowercase
//!   -t          no types: every value is a string
//!   -q, -v      errors only; or debug messages too
//!   -s section  only that section's entries
//!
//! Each entry is printed as `section.key = type:value`, in the file's order, then a summary
//! line. Messages go to stderr; a file that doesn't parse exits with status 1.
#![forbid(unsafe_code)]

use std::ffi::OsString;
use std::fs::File;
use std::io::{self, Write};
use std::os::unix::ffi::OsStrExt;
use std::process::exit;

use kvconf_rs::doc::Doc;
use kvconf_rs::log::{level_name, Options, CASE_FOLD, DEBUG, ERROR, NO_TYPES};
use kvconf_rs::parse::read_into;
use kvconf_rs::value::STR;

fn usage() -> ! {
    eprintln!("usage: kvdump [-f] [-t] [-q | -v] [-s section] file");
    exit(2);
}

/// One message line on stderr, as the C's `fprintf(stderr, ...)`.
fn message(parts: &[&[u8]]) {
    let mut line = parts.concat();
    line.push(b'\n');
    let _ = io::stderr().write_all(&line);
}

fn main() {
    let args: Vec<OsString> = std::env::args_os().collect();
    let mut opt = Options::default();
    let mut section: Option<Vec<u8>> = None;
    let mut i = 1;
    while i < args.len() {
        let arg = args[i].as_bytes();
        if arg.len() < 2 || arg[0] != b'-' {
            break;
        }
        match arg {
            b"-f" => opt.flags |= CASE_FOLD,
            b"-t" => opt.flags |= NO_TYPES,
            b"-q" => opt.log_level = ERROR,
            b"-v" => opt.log_level = DEBUG,
            b"-s" if i + 1 < args.len() => {
                i += 1;
                section = Some(args[i].as_bytes().to_vec());
            }
            _ => usage(),
        }
        i += 1;
    }
    if i + 1 != args.len() {
        usage();
    }
    let file = args[i].as_bytes();
    let sink = |level: i32, text: &[u8]| {
        message(&[b"kvdump: ", file, b": ", level_name(level).as_bytes(), b": ", text]);
    };
    opt.log = Some(&sink);

    let Ok(input) = File::open(std::path::Path::new(&args[i])) else {
        message(&[b"kvdump: ", file, b": cannot open"]);
        exit(1);
    };
    let mut doc = Doc::default();
    if let Err(e) = read_into(&mut doc, input, &opt) {
        let at = format!(":{}:{}: ", e.line, e.column);
        message(&[b"kvdump: ", file, at.as_bytes(), e.message.as_bytes()]);
        exit(1);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let mut shown = 0;
    for e in doc.each(section.as_deref()) {
        let mut line = e.section.clone();
        if !e.section.is_empty() {
            line.push(b'.');
        }
        line.extend_from_slice(&e.key);
        line.extend_from_slice(b" = ");
        line.extend_from_slice(e.value.type_name().as_bytes());
        line.push(b':');
        line.extend_from_slice(&e.value.format());
        line.push(b'\n');
        let _ = out.write_all(&line);
        shown += 1;
    }
    let stats = doc.stats();
    let _ = writeln!(
        out,
        "# {shown} of {} entries, {} sections, {} strings",
        stats.entries, stats.sections, stats.by_type[STR as usize]
    );
    let _ = out.flush();
}

