//! kvdump's output and messages for the sample files, as tests/dump.sh compared them
//! (CodeCoreMorph, D-68): they stand for that test once the Make build is gone.
#![forbid(unsafe_code)]

use std::process::{Command, Output};

const TESTS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../tests");

/// kvdump run in tests/, as dump.sh ran it.
fn kvdump(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_kvdump"))
        .args(args)
        .current_dir(TESTS)
        .output()
        .expect("kvdump runs")
}

fn expected(name: &str) -> Vec<u8> {
    std::fs::read(format!("{TESTS}/{name}")).expect("the expected output is there")
}

#[test]
fn sample() {
    let out = kvdump(&["sample.conf"]);
    assert!(out.status.success());
    assert_eq!(out.stdout, expected("sample.out"));
    assert_eq!(out.stderr, expected("sample.warn"));
}

#[test]
fn one_section_without_types() {
    let out = kvdump(&["-t", "-s", "server", "sample.conf"]);
    assert!(out.status.success());
    assert_eq!(out.stdout, expected("sample-server.out"));
}

#[test]
fn a_file_that_doesnt_parse() {
    let out = kvdump(&["-q", "broken.conf"]);
    assert_eq!(out.status.code(), Some(1));
    assert!(out.stdout.is_empty());
    assert_eq!(out.stderr, expected("broken.warn"));
}

#[test]
fn usage() {
    let out = kvdump(&[]);
    assert_eq!(out.status.code(), Some(2));
    assert_eq!(out.stderr, b"usage: kvdump [-f] [-t] [-q | -v] [-s section] file\n");
}

