//! Translated from tests/test_doc.c (CodeCoreMorph, D-68). automake ran the C program as one
//! test, `make:tests/test_doc`; each of its test functions is a Rust test here, and the map
//! gives the C test all of them.
#![forbid(unsafe_code)]

use kvconf_rs::doc::{Doc, Set};
use kvconf_rs::log::{Error, CASE_FOLD};
use kvconf_rs::strutil::NAME_MAX;
use kvconf_rs::value::{Value, BOOL, INT, REAL, STR};

fn set(doc: &mut Doc, section: Option<&str>, key: &str, text: &str, line: i32) -> Result<Set, Error> {
    let value = Value::parse(text.as_bytes(), 0)?;
    doc.set(section.map(str::as_bytes), key.as_bytes(), &value, line)
}

#[test]
fn set_and_find() {
    let mut doc = Doc::default();
    assert!(doc.is_empty());
    assert_eq!(set(&mut doc, None, "name", "\"demo\"", 1), Ok(Set::Added));
    assert_eq!(set(&mut doc, Some("server"), "port", "8080", 3), Ok(Set::Added));
    assert_eq!(set(&mut doc, Some("server"), "host", "localhost", 4), Ok(Set::Added));
    assert_eq!(set(&mut doc, Some("server"), "port", "8081", 9), Ok(Set::Replaced));
    assert_eq!(doc.len(), 3);
    let port = &doc.entries()[1];
    assert_eq!(port.key, b"port");
    assert_eq!((&port.value, port.line), (&Value::Int(8081), 9));
    let name = doc.find(Some(b""), b"name");
    assert!(name.is_some());
    assert!(std::ptr::eq(name.unwrap_or(port), doc.find(None, b"name").unwrap_or(port)));
    assert!(doc.find(Some(b"server"), b"name").is_none());
    assert!(doc.find(Some(b"Server"), b"port").is_none());
}

#[test]
fn many() {
    let mut doc = Doc::default();
    for i in 0..100 {
        assert_eq!(set(&mut doc, Some("s"), &format!("k{i}"), "1", i), Ok(Set::Added));
    }
    assert_eq!(doc.len(), 100);
    assert_eq!(doc.entries()[99].key, b"k99");
}

#[test]
fn case_fold() {
    let mut doc = Doc::new(CASE_FOLD);
    assert_eq!(set(&mut doc, Some("Server"), "Port", "1", 1), Ok(Set::Added));
    assert_eq!(doc.entries()[0].section, b"server");
    assert_eq!(doc.entries()[0].key, b"port");
    assert!(doc.find(Some(b"SERVER"), b"pOrt").is_some());
    assert_eq!(set(&mut doc, Some("server"), "PORT", "2", 2), Ok(Set::Replaced));
}

#[test]
fn long_names() {
    let mut doc = Doc::default();
    let name = "n".repeat(NAME_MAX);
    assert_eq!(set(&mut doc, Some("s"), &name, "1", 1), Err(Error::Range));
    assert_eq!(set(&mut doc, Some("s"), &name[1..], "1", 1), Ok(Set::Added));
    assert_eq!(doc.len(), 1);
}

#[test]
fn typed_reads() {
    let mut doc = Doc::default();
    for (key, text, line) in [("port", "8080", 1), ("ratio", "0.5", 2), ("debug", "on", 3), ("name", "\"x\"", 4)] {
        assert_eq!(set(&mut doc, Some(""), key, text, line), Ok(Set::Added));
    }
    assert_eq!(doc.get_int(None, b"port"), Ok(8080));
    assert_eq!(doc.get_int(None, b"ratio"), Err(Error::Type));
    assert_eq!(doc.get_int(None, b"missing"), Err(Error::NotFound));
    assert_eq!(doc.get_real(None, b"ratio"), Ok(0.5));
    assert_eq!(doc.get_real(None, b"port"), Ok(8080.0));
    assert_eq!(doc.get_real(None, b"debug"), Err(Error::Type));
    assert_eq!(doc.get_bool(None, b"debug"), Ok(true));
    assert_eq!(doc.get_bool(None, b"port"), Err(Error::Type));
    assert_eq!(doc.get_str(None, b"name"), Some(&b"x"[..]));
    assert_eq!(doc.get_str(None, b"port"), None);
    assert_eq!(doc.get_str(None, b"missing"), None);
}

#[test]
fn each() {
    let mut doc = Doc::default();
    for (section, key, line) in [("a", "x", 1), ("b", "y", 2), ("a", "z", 3)] {
        assert_eq!(set(&mut doc, Some(section), key, "1", line), Ok(Set::Added));
    }
    let keys = |section: Option<&[u8]>| doc.each(section).flat_map(|e| e.key.clone()).collect::<Vec<u8>>();
    assert_eq!(keys(None), b"xyz");
    assert_eq!(keys(Some(b"a")), b"xz");
    // kv_each's early stop is the iterator's: the visit ends at the second entry.
    assert_eq!(doc.each(None).position(|e| e.key == b"y"), Some(1));
}

#[test]
fn stats() {
    let mut doc = Doc::default();
    let empty = doc.stats();
    assert_eq!((empty.entries, empty.sections), (0, 0));
    assert_eq!(set(&mut doc, None, "a", "1", 1), Ok(Set::Added));
    assert_eq!(set(&mut doc, Some("s"), "b", "\"four\"", 2), Ok(Set::Added));
    assert_eq!(set(&mut doc, Some("s"), "c", "\"sixsix\"", 3), Ok(Set::Added));
    assert_eq!(set(&mut doc, Some("t"), "d", "yes", 4), Ok(Set::Added));
    let stats = doc.stats();
    assert_eq!((stats.entries, stats.sections), (4, 3));
    let by_type = |t: i32| stats.by_type[usize::try_from(t).unwrap_or(0)];
    assert_eq!((by_type(INT), by_type(STR), by_type(BOOL), by_type(REAL)), (1, 2, 1, 0));
    assert_eq!(stats.longest_string, 6);
}

//! Translated from tests/test_log.c (CodeCoreMorph, D-68). automake ran the C program as one
//! test, `make:tests/test_log`; each of its test functions is a Rust test here, and the map
//! gives the C test all of them.
#![forbid(unsafe_code)]

use std::cell::RefCell;

use kvconf_rs::log::{level_name, strerror, Error, Options, DEBUG, ERROR, INFO, MESSAGE_MAX, WARN};

/// The messages a sink got, with their levels.
type Seen = RefCell<Vec<(i32, Vec<u8>)>>;

fn collect(seen: &Seen) -> impl Fn(i32, &[u8]) + '_ {
    move |level, message| seen.borrow_mut().push((level, message.to_vec()))
}

#[test]
fn defaults() {
    let opt = Options::default();
    assert_eq!(opt.flags, 0);
    assert_eq!(opt.comment, b'#');
    assert_eq!(opt.log_level, WARN);
    assert!(opt.log.is_none());
}

#[test]
fn sink() {
    let seen = Seen::default();
    let sink = collect(&seen);
    let opt = Options { log: Some(&sink), ..Options::default() };
    opt.log(WARN, format_args!("line {}: {} is set again", 3, "port"));
    // kv_vlog's va_list is format_args! here.
    opt.log(ERROR, format_args!("{}={:05.1}", "ratio", 2.25));
    opt.write(WARN, b"100% done");
    assert_eq!(
        *seen.borrow(),
        vec![
            (WARN, b"line 3: port is set again".to_vec()),
            (ERROR, b"ratio=002.2".to_vec()),
            (WARN, b"100% done".to_vec()),
        ]
    );
}

#[test]
fn levels() {
    let seen = Seen::default();
    let sink = collect(&seen);
    let mut opt = Options { log: Some(&sink), ..Options::default() };
    opt.log(INFO, format_args!("dropped"));
    opt.log(DEBUG, format_args!("dropped"));
    opt.write(INFO, b"dropped");
    assert!(seen.borrow().is_empty());
    opt.log_level = DEBUG;
    opt.log(DEBUG, format_args!("kept"));
    assert_eq!(*seen.borrow(), vec![(DEBUG, b"kept".to_vec())]);
    opt.log_level = -1;
    opt.log(ERROR, format_args!("dropped"));
    assert_eq!(seen.borrow().len(), 1);
}

#[test]
fn long_message() {
    let seen = Seen::default();
    let sink = collect(&seen);
    let opt = Options { log: Some(&sink), ..Options::default() };
    let word = "x".repeat(MESSAGE_MAX * 2 - 1);
    opt.log(ERROR, format_args!("{word}"));
    assert_eq!(seen.borrow()[0].1.len(), MESSAGE_MAX - 1);
    // A message already formatted goes whole; the C test's own buffer cut it.
    opt.write(ERROR, word.as_bytes());
    assert_eq!(seen.borrow()[1].1.len(), word.len());
