//! test, `make:tests/test_parse`; each of its test functions is a Rust test here, and the map
//! gives the C test all of them.
#![forbid(unsafe_code)]

use std::cell::RefCell;

use kvconf_rs::doc::Doc;
use kvconf_rs::log::{Error, Options, ALLOW_DUP, CASE_FOLD};
use kvconf_rs::parse::{parse_into, read_into, scan, ParseError, Stop};

/// The entries a scan found, as `line:section/key=raw|`, and how it ended.
fn events(text: &[u8], opt: &Options, stop_at: usize) -> (Result<(), Stop>, String, usize) {
    let mut log = String::new();
    let mut count = 0;
    let result = scan(text, opt, |section, key, raw, line| {
        count += 1;
        let [s, k, r] = [section, key, raw].map(String::from_utf8_lossy);
        log += &format!("{line}:{s}/{k}={r}|");
        if count == stop_at {
            99
        } else {
            0
        }
    });
    (result, log, count)
}

/// The messages the options' sink got.
type Seen = RefCell<Vec<Vec<u8>>>;

fn quiet(seen: &Seen) -> impl Fn(i32, &[u8]) + '_ {
    move |_, message| seen.borrow_mut().push(message.to_vec())
}

fn error(code: Error, line: i32, column: i32, message: &str) -> ParseError {
    ParseError { code, line, column, message: message.to_string() }
}

#[test]
fn scan_entries() {
    let seen = Seen::default();
    let sink = quiet(&seen);
    let mut opt = Options { log: Some(&sink), ..Options::default() };
    let text = b"a = 1\r\n; note\n# note\n\n[ srv ]  # main\nb=two words  # c\n\
                 c = \"q;#\"  ; after\nd = x#y\n";
    let (result, log, _) = events(text, &opt, 0);
    assert_eq!(result, Ok(()));
    assert_eq!(log, "1:/a=1|6:srv/b=two words|7:srv/c=\"q;#\"|8:srv/d=x#y|");
    assert!(seen.borrow().is_empty());
    opt.comment = b'!';
    let (_, log, _) = events(b"a = 1 ! no\n! skip\nb = 2 # kept\n", &opt, 0);
    assert_eq!(log, "1:/a=1|3:/b=2 # kept|");
    let defaults = Options::default();
    assert_eq!(events(b"a = 1\nb = 2\nc = 3\n", &defaults, 0).2, 3);
    let (result, _, count) = events(b"a = 1\nb = 2\nc = 3\n", &defaults, 2);
    assert_eq!((result, count), (Err(Stop::Visitor(99)), 2));
    assert_eq!(events(b"a = 1\nb = 2", &defaults, 0).2, 2);
    assert_eq!(events(&b"x = 1\ny = 2\n"[..6], &defaults, 0).2, 1);
}

#[test]
fn errors() {
    let seen = Seen::default();
    let sink = quiet(&seen);
    let opt = Options { log: Some(&sink), ..Options::default() };
    let failed = |text: &[u8]| match events(text, &opt, 0).0 {
        Err(Stop::Error(e)) => Some(e),
        _ => None,
    };
    assert_eq!(failed(b"a = 1\n  [open\n"), Some(error(Error::Syntax, 2, 3, "missing ']'")));
    assert_eq!(*seen.borrow(), vec![b"line 2, column 3: missing ']'".to_vec()]);
    assert_eq!(failed(b"just words\n"), Some(error(Error::Syntax, 1, 0, "expected '='")));
    assert_eq!(seen.borrow().last().map(Vec::as_slice), Some(&b"line 1: expected '='"[..]));
    assert_eq!(failed(b"bad key = 1\n"), Some(error(Error::Syntax, 1, 1, "bad key name")));
    assert_eq!(failed(b"[a b]\n"), Some(error(Error::Syntax, 1, 2, "bad section name")));
    assert_eq!(failed(b"[a] x\n"), Some(error(Error::Syntax, 1, 4, "text after ']'")));
    assert_eq!(
        failed(b"k = \"a\" b\n"),
        Some(error(Error::Syntax, 1, 8, "text after the closing quote"))
    );
    assert_eq!(failed(b"k = \"a\\\"\n"), Some(error(Error::Syntax, 1, 5, "missing '\"'")));
    let long = format!("{} = 1\n", "k".repeat(69));
    assert_eq!(failed(long.as_bytes()), Some(error(Error::Range, 1, 1, "key name too long")));
}

#[test]
fn parse_string() {
    let seen = Seen::default();
    let sink = quiet(&seen);
    let mut opt = Options { log: Some(&sink), ..Options::default() };
    let mut doc = Doc::default();
    let text = b"top = yes\n[net]\nport = 80\nport = 81\nhost = \"h\"\n";
    assert_eq!(parse_into(&mut doc, text, &opt), Ok(()));
    assert_eq!(doc.len(), 3);
    assert_eq!(doc.get_int(Some(b"net"), b"port"), Ok(81));
    assert_eq!(*seen.borrow(), vec![b"line 4: net.port is set again".to_vec()]);

    seen.borrow_mut().clear();
    opt.flags = ALLOW_DUP | CASE_FOLD;
    let mut doc = Doc::default();
    assert_eq!(parse_into(&mut doc, b"[Net]\nPort = 80\nport = 81\n", &opt), Ok(()));
    assert_eq!((doc.len(), doc.flags), (1, opt.flags));
    assert!(seen.borrow().is_empty());
    assert_eq!(doc.entries()[0].section, b"net");

    opt.flags = 0;
    let mut doc = Doc::default();
    assert_eq!(
        parse_into(&mut doc, b"a = 1\nbig = 1e999\n", &opt),
        Err(error(Error::Range, 2, 0, "big: value out of range"))
    );
    assert_eq!(seen.borrow().last().map(Vec::as_slice), Some(&b"line 2: big: value out of range"[..]));
    assert_eq!(doc.len(), 1);

    assert_eq!(Doc::parse(b"", &Options::default()).map(|d| d.len()), Ok(0));
}

#[test]
fn parse_file() {
    let text: String = (0..500).map(|i| format!("[s{i}]\nkey = \"value number {i}\"\n")).collect();
    let mut doc = Doc::default();
    assert_eq!(read_into(&mut doc, text.as_bytes(), &Options::default()), Ok(()));
    assert_eq!(doc.len(), 500);
    assert_eq!(doc.get_str(Some(b"s499"), b"key"), Some(&b"value number 499"[..]));
}

