use kvconf_rs::log::{Error, NO_TYPES};
use kvconf_rs::value::{type_name, Value, INT, NONE, STR};

fn parse(text: &str, flags: u32) -> Result<Value, Error> {
    Value::parse(text.as_bytes(), flags)
}

fn text(s: &str) -> Value {
    Value::Str(s.as_bytes().to_vec())
}

#[test]
fn integers() {
    assert_eq!(parse("8080", 0), Ok(Value::Int(8080)));
    assert_eq!(parse("  -42 ", 0), Ok(Value::Int(-42)));
    assert_eq!(parse("0x1f", 0), Ok(Value::Int(31)));
    assert_eq!(parse("010", 0), Ok(Value::Int(8)));
    assert_eq!(parse("08", 0), Ok(text("08")));
    assert_eq!(parse("99999999999999999999", 0), Err(Error::Range));
}

#[test]
fn reals() {
    assert_eq!(parse("2.5", 0), Ok(Value::Real(2.5)));
    assert_eq!(parse("-.5e-3", 0), Ok(Value::Real(-0.0005)));
    assert_eq!(parse("1e5", 0), Ok(Value::Real(100_000.0)));
    assert_eq!(parse("1e999", 0), Err(Error::Range));
    assert_eq!(parse("inf", 0), Ok(text("inf")));
}

#[test]
fn booleans() {
    assert_eq!(parse("yes", 0), Ok(Value::Bool(true)));
    assert_eq!(parse("On", 0), Ok(Value::Bool(true)));
    assert_eq!(parse("FALSE", 0), Ok(Value::Bool(false)));
    assert_eq!(parse("y", 0), Ok(text("y")));
}

#[test]
fn strings() {
    let quoted = parse(r#""say \"hi\"\tnow""#, 0);
    assert_eq!(quoted, Ok(text("say \"hi\"\tnow")));
    assert_eq!(quoted.ok().and_then(|v| v.as_str().map(<[u8]>::len)), Some(12));
    assert_eq!(parse(r#""bad \q""#, 0), Err(Error::Syntax));
    assert_eq!(parse("\"open", 0), Err(Error::Syntax));
    assert_eq!(parse("", 0), Ok(text("")));
    assert_eq!(parse("8080", NO_TYPES), Ok(text("8080")));
    // kv_value_set_str(&v, "abcdef", 3), and a cleared value.
    assert_eq!(Value::Str(b"abcdef"[..3].to_vec()), text("abc"));
    assert_eq!(Value::default(), Value::None);
}

#[test]
fn copy() {
    let a = text("text");
    let b = a.clone();
    assert_eq!(b, text("text"));
    // The copy has bytes of its own.
    assert_ne!(a.as_str().map(<[u8]>::as_ptr), b.as_str().map(<[u8]>::as_ptr));
    assert_eq!(Value::Int(7).clone(), Value::Int(7));
}

fn formatted(text: &str) -> String {
    let value = parse(text, 0).unwrap_or_default();
    String::from_utf8_lossy(&value.format()).into_owned()
}

#[test]
fn format() {
    assert_eq!(formatted("-12"), "-12");
    assert_eq!(formatted("2.5"), "2.5");
    assert_eq!(formatted("1e-5"), "1e-05");
    assert_eq!(formatted("100000.0"), "100000");
    assert_eq!(formatted("1e6"), "1e+06");
    assert_eq!(formatted("0.1234567"), "0.123457");
    assert_eq!(formatted("off"), "false");
    assert_eq!(formatted(r#""a\"b\nc""#), r#""a\"b\nc""#);
    // The whole text, which C cut to its buffer while returning this length.
    assert_eq!(text("abc").format(), b"\"abc\"");
    assert_eq!(text("abc").format().len(), 5);
    assert!(Value::None.format().is_empty());
}

#[test]
fn type_names() {
    assert_eq!(type_name(INT), "int");
    assert_eq!(type_name(STR), "string");
    assert_eq!(type_name(NONE), "none");
    assert_eq!(type_name(9), "?");
    assert_eq!(Value::Bool(true).type_name(), "bool");
}

